head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};

scwin.onpageload = function() {
	var rowJSON = {
		"Personal Info" : {
			"Name" : "Lee",
			"Age" : 50,
			"Married" : false
		},
		"Region" : "Seoul",
		"Carrier" : true
	};
	var obj = {
		"title" : "Test",
		"windowId" : "001",
		"frameMode" : "wframe",
		"src" : "WESD_1026_tab_sub.xml",
		"confirmTrueAction" : "newWindow",
		"options" : {
			"fixed" : true
		},
		"dataObject" : {
			"type" : "json",
			"name" : "windowParam",
			"data" : rowJSON
		}
	};
	for (var i = 0; i < 5; i++) {
		obj.title = "test_" + i;
		obj.windowId = i;
		window1.createWindow(obj);
	}
};

scwin.trigger1_onclick = function(e) {
	window1.setFocus("test_0");
};

scwin.checkVal1 = function() {
	return scwin.__getJq('#window1_nameLayer_' + $p.id + 'window1_subWindow0').hasClass('w2windowContainer_nameLayer w2windowContainer_selectedNameLayer');
};
